import{createMuseLoginNotice}from'./mopix-session.js';
import{createStudioIcon}from'./studio-icons.js?v=24';
export function createTopNav(React){const{createElement:h}=React,Icon=createStudioIcon(React),LoginNotice=createMuseLoginNotice(React);return function TopNav({active,onNavigate}){
 const items=[['home','Trang chủ','home'],['quickCreate','Tạo ảnh','background'],['image','Chỉnh ảnh','detail'],['design','Thiết kế','concept'],['shape3d','Shape 3D','product'],['videoQuick','Video','video'],['videoStudio','Phim','film'],['nodeCanvas','Canvas','nodes'],['upscale','Upscale 4K','enhance'],['advancedPrompt','Prompt','prompt'],['refs','Thư viện','grid'],['settings','Cài đặt','sliders']];
 return h(React.Fragment,null,h(LoginNotice,{onNavigate}),h('header',{className:'muse-global-nav'},h('button',{type:'button',className:'mopix-nav-brand','aria-label':'MOPIX · Trang chủ',onClick:()=>onNavigate('home')},h('img',{src:'/assets/mopix-logo.svg',alt:'MOPIX'})),h('nav',{'aria-label':'Điều hướng chính'},...items.map(([id,label,icon])=>{const selected=active===id||(id==='videoQuick'&&['videoMerge','videoBoard'].includes(active))||(id==='image'&&['quick','refine','product'].includes(active));return h('button',{key:id,type:'button',title:label,'aria-label':id==='advancedPrompt'?'Prompt nâng cao':label,'aria-current':selected?'page':undefined,onClick:()=>onNavigate(id)},h(Icon,{name:icon,size:18}),h('span',{className:'nav-item-label'},label))}))));
}}
